TEST(CeltBands, MatchesReference) {
    for (const BandsCase& test : kCases) {
        const int m = 1 << test.lm;
        const int n = m * 100;
        std::vector<float> x(n, 0.0f);
        std::vector<float> y(test.channels == 2 ? n : 0, 0.0f);
        std::vector<uint8_t> masks(test.channels * 21, 0);
        player::audio::opus::BandsParams params;
        params.short_blocks = test.short_blocks;
        params.spread = static_cast<player::audio::opus::Spread>(test.spread);
        params.dual_stereo = test.dual_stereo;
        params.intensity = test.intensity;
        params.tf_res = test.tf_res.data();
        params.pulses = test.pulses.data();
        params.total_bits = 3000;
        params.balance = 0;
        params.lm = test.lm;
        params.coded_bands = test.coded_bands;
        player::audio::opus::RangeDecoder decoder(test.packet.data(), test.packet.size());
        uint32_t seed = test.seed;
        player::audio::opus::quantAllBands(decoder, params, test.channels, x.data(),
                                           test.channels == 2 ? y.data() : nullptr,
                                           masks.data(), seed);
        EXPECT_EQ(seed, test.expected_seed);
        EXPECT_EQ(decoder.tellFrac(), test.expected_tell);
        for (int i = 0; i < n; ++i) {
            EXPECT_NEAR(x[i], test.expected_x[i], 1e-5f) << "x " << i;
        }
        for (int i = 0; i < static_cast<int>(y.size()); ++i) {
            EXPECT_NEAR(y[i], test.expected_y[i], 1e-5f) << "y " << i;
        }
        for (int i = 0; i < static_cast<int>(masks.size()); ++i) {
            EXPECT_EQ(masks[i], test.expected_masks[i]) << "mask " << i;
        }
    }
}
